-- 시연용 문서함 자료 (명세 7장, DEC-098). scripts/demo-docbox-data.py가 만든 파일이다. 직접 고치지 않는다
-- 폴더 2개, 파일 7개, 공유 1개. 내용은 모두 가상(NFR-002)
-- 이름이 R__seed_work_docbox_demo라 초기 데이터·시연 업무 다음에 돈다. 문서함에 무엇이든 있거나 번호 범위(200001~)가 쓰였거나 쓸 계정이 없으면 전체를 건너뛴다

SET @base = TIMESTAMP('2026-11-02 12:00:00');
SET @a_bn1_cmdr = (SELECT id FROM account WHERE login_id = 'bn1-cmdr' AND active = TRUE);
SET @a_bn1_co1_cmdr = (SELECT id FROM account WHERE login_id = 'bn1-co1-cmdr' AND active = TRUE);
SET @a_bn1_co1_s1_lead = (SELECT id FROM account WHERE login_id = 'bn1-co1-s1-lead' AND active = TRUE);
SET @a_bn1_co1_s1_m1 = (SELECT id FROM account WHERE login_id = 'bn1-co1-s1-m1' AND active = TRUE);
SET @a_bn1_co1_s2_m1 = (SELECT id FROM account WHERE login_id = 'bn1-co1-s2-m1' AND active = TRUE);
SET @ok = (SELECT COUNT(*) FROM doc_node) = 0
    AND (SELECT COALESCE(MAX(id), 0) FROM stored_file) < 200001
    AND @a_bn1_cmdr IS NOT NULL
    AND @a_bn1_co1_cmdr IS NOT NULL
    AND @a_bn1_co1_s1_lead IS NOT NULL
    AND @a_bn1_co1_s1_m1 IS NOT NULL
    AND @a_bn1_co1_s2_m1 IS NOT NULL;

INSERT INTO stored_file (id, purpose, linked, uploaded_by_account_id, original_name, extension, size, sha256, created_at, linked_at)
SELECT * FROM (VALUES
    ROW(200002, 'DOC_BOX', TRUE, @a_bn1_co1_cmdr, '발전기_정비지침.hwp', 'hwp', 5632, 'e5526d83547f1336f028b433a79d7ae955ef748394e3cddd677bdf5411931a58', @base - INTERVAL 41760 MINUTE, @base - INTERVAL 41760 MINUTE),
    ROW(200003, 'DOC_BOX', TRUE, @a_bn1_co1_cmdr, '회의록_2026-10.docx', 'docx', 37092, 'f022043e77be0c968be0f14eb095b13a02fbd6765b878a60f446f4e65923a829', @base - INTERVAL 25920 MINUTE, @base - INTERVAL 25920 MINUTE),
    ROW(200004, 'DOC_BOX', TRUE, @a_bn1_co1_s1_lead, '통신장비_점검표.xlsx', 'xlsx', 6620, '9c1b86daeb1f6e77c5bc126ce514cfde0c03f0ad7d4d38d079c9d6a8da17c1e4', @base - INTERVAL 36000 MINUTE, @base - INTERVAL 36000 MINUTE),
    ROW(200005, 'DOC_BOX', TRUE, @a_bn1_co1_s1_m1, '전화회선_이동_작업안내.pdf', 'pdf', 66009, 'e60fea4e117a8d3607787f9e1f8a86248554fe6c192119688a70a3c338873c47', @base - INTERVAL 8640 MINUTE, @base - INTERVAL 8640 MINUTE),
    ROW(200007, 'DOC_BOX', TRUE, @a_bn1_co1_s1_lead, '무전기_운용교육.pptx', 'pptx', 31257, 'ac44cf3675ca15b63d83eb0e5f9f739fd1c15c64682e804b2cf1ea5f8acff24d', @base - INTERVAL 56160 MINUTE, @base - INTERVAL 56160 MINUTE),
    ROW(200008, 'DOC_BOX', TRUE, @a_bn1_cmdr, '비상_연락_절차.hwpx', 'hwpx', 6981, '5f2b6e0d99f733779aa939258ac482b6c10f6be69b291cf20a80422abad278ed', @base - INTERVAL 72000 MINUTE, @base - INTERVAL 72000 MINUTE),
    ROW(200009, 'DOC_BOX', TRUE, @a_bn1_co1_s2_m1, '인수인계_메모.txt', 'txt', 316, '682146eccfbd98c72d102dfb96efd94095b9a0fce84d3d9eb9e0196d7b0b5b54', @base - INTERVAL 4320 MINUTE, @base - INTERVAL 4320 MINUTE)
) AS v WHERE @ok;

INSERT INTO stored_file_body (file_id, data) SELECT 200002, X'' FROM DUAL WHERE @ok;

INSERT INTO stored_file_body (file_id, data) SELECT 200003, X'' FROM DUAL WHERE @ok;

INSERT INTO stored_file_body (file_id, data) SELECT 200004, X'' FROM DUAL WHERE @ok;

INSERT INTO stored_file_body (file_id, data) SELECT 200005, X'' FROM DUAL WHERE @ok;

INSERT INTO stored_file_body (file_id, data) SELECT 200007, X'' FROM DUAL WHERE @ok;

INSERT INTO stored_file_body (file_id, data) SELECT 200008, X'' FROM DUAL WHERE @ok;

INSERT INTO stored_file_body (file_id, data) SELECT 200009, X'' FROM DUAL WHERE @ok;

INSERT INTO doc_box (department_id, created_at)
SELECT * FROM (VALUES
    ROW(1, @base - INTERVAL 86400 MINUTE),
    ROW(2, @base - INTERVAL 86400 MINUTE),
    ROW(5, @base - INTERVAL 86400 MINUTE),
    ROW(6, @base - INTERVAL 86400 MINUTE)
) AS v WHERE @ok;

INSERT INTO doc_node (id, department_id, parent_id, kind, name, file_id, size, created_by_account_id, created_at, updated_by_account_id, updated_at)
SELECT * FROM (VALUES
    ROW(200001, 2, NULL, 'FOLDER', '발전기', NULL, 0, @a_bn1_co1_cmdr, @base - INTERVAL 43200 MINUTE, @a_bn1_co1_cmdr, @base - INTERVAL 43200 MINUTE),
    ROW(200002, 2, 200001, 'FILE', '발전기_정비지침.hwp', 200002, 5632, @a_bn1_co1_cmdr, @base - INTERVAL 41760 MINUTE, @a_bn1_co1_cmdr, @base - INTERVAL 41760 MINUTE),
    ROW(200003, 2, NULL, 'FILE', '회의록_2026-10.docx', 200003, 37092, @a_bn1_co1_cmdr, @base - INTERVAL 25920 MINUTE, @a_bn1_co1_cmdr, @base - INTERVAL 25920 MINUTE),
    ROW(200004, 5, NULL, 'FILE', '통신장비_점검표.xlsx', 200004, 6620, @a_bn1_co1_s1_lead, @base - INTERVAL 36000 MINUTE, @a_bn1_co1_s1_lead, @base - INTERVAL 36000 MINUTE),
    ROW(200005, 5, NULL, 'FILE', '전화회선_이동_작업안내.pdf', 200005, 66009, @a_bn1_co1_s1_m1, @base - INTERVAL 8640 MINUTE, @a_bn1_co1_s1_m1, @base - INTERVAL 8640 MINUTE),
    ROW(200006, 5, NULL, 'FOLDER', '교육자료', NULL, 0, @a_bn1_co1_s1_lead, @base - INTERVAL 57600 MINUTE, @a_bn1_co1_s1_lead, @base - INTERVAL 57600 MINUTE),
    ROW(200007, 5, 200006, 'FILE', '무전기_운용교육.pptx', 200007, 31257, @a_bn1_co1_s1_lead, @base - INTERVAL 56160 MINUTE, @a_bn1_co1_s1_lead, @base - INTERVAL 56160 MINUTE),
    ROW(200008, 1, NULL, 'FILE', '비상_연락_절차.hwpx', 200008, 6981, @a_bn1_cmdr, @base - INTERVAL 72000 MINUTE, @a_bn1_cmdr, @base - INTERVAL 72000 MINUTE),
    ROW(200009, 6, NULL, 'FILE', '인수인계_메모.txt', 200009, 316, @a_bn1_co1_s2_m1, @base - INTERVAL 4320 MINUTE, @a_bn1_co1_s2_m1, @base - INTERVAL 4320 MINUTE)
