INSERT INTO doc_share (id, node_id, personnel_id, department_id, created_by_account_id, created_at)
SELECT * FROM (VALUES
    ROW(200001, 200004, NULL, 6, @a_bn1_co1_s1_lead, @base - INTERVAL 34560 MINUTE)
) AS v WHERE @ok;

SELECT @ok AS docbox_demo_applied, (SELECT COUNT(*) FROM doc_node WHERE id >= 200001) AS doc_nodes;
